enum SdkOperationError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case InvalidArgument(detail: String
    )
    case Unsupported(detail: String
    )
    case Unreachable
    case Timeout
    case Conflict(detail: String
    )
    case InsufficientStorage
    case RemoteFailure(detail: String
    )
    case CommittedWithWarning(detail: String
    )
    case CommittedButCleanupFailed(detail: String
    )
    case RecoveryFailed(detail: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension SdkOperationError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSdkOperationError: FfiConverterRustBuffer {
    typealias SwiftType = SdkOperationError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SdkOperationError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidArgument(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Unsupported(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Unreachable
        case 4: return .Timeout
        case 5: return .Conflict(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 6: return .InsufficientStorage
        case 7: return .RemoteFailure(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 8: return .CommittedWithWarning(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 9: return .CommittedButCleanupFailed(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 10: return .RecoveryFailed(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SdkOperationError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidArgument(detail):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Unsupported(detail):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(detail, into: &buf)
            
        
        case .Unreachable:
            writeInt(&buf, Int32(3))
        
        
        case .Timeout:
            writeInt(&buf, Int32(4))
        
        
        case let .Conflict(detail):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(detail, into: &buf)
            
        
        case .InsufficientStorage:
            writeInt(&buf, Int32(6))
        
        
        case let .RemoteFailure(detail):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .CommittedWithWarning(detail):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .CommittedButCleanupFailed(detail):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .RecoveryFailed(detail):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


